<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Services\AuditService; use App\Support\BrandContext; use Illuminate\Http\Request;
class BrandSettingsController extends Controller { public function edit(BrandContext $ctx){$this->authorize('update',$ctx->brand());return view('admin.brand-settings');} public function update(Request $r,BrandContext $ctx,AuditService $audit){$b=$ctx->brand();$this->authorize('update',$b);$rules=['name'=>'required|string|max:160','primary_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','secondary_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','accent_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','background_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','text_color'=>'required|regex:/^#[0-9A-Fa-f]{6}$/','seo_title'=>'nullable|string|max:255','seo_description'=>'nullable|string|max:1000','eyebrow'=>'nullable|string|max:100','hero_title'=>'nullable|string|max:160','hero_note'=>'nullable|string|max:255'];if($r->user()->isSuperAdmin())$rules+=['slug'=>'required|alpha_dash|max:100|unique:brands,slug,'.$b->id,'domain'=>['nullable','max:255','regex:/^(?=.{1,253}$)(?!-)[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*(?<!-)$/'],'status'=>'required|in:active,inactive'];$data=$r->validate($rules);$theme=['eyebrow'=>$data['eyebrow']??null,'hero_title'=>$data['hero_title']??null,'hero_note'=>$data['hero_note']??null];unset($data['eyebrow'],$data['hero_title'],$data['hero_note']);$data['theme_settings']=$theme;$before=$b->toArray();$b->update($data);$audit->record('brands.settings_updated',$b,$before,$b->fresh()->toArray());return back()->with('status','品牌設定已更新。');}}
